1	package nettrace
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/netip"
8		"sync"
9		"syscall"
10		"time"
11	)
12	
13	// prober opens one probe connection per TTL. The system implementation lives
14	// in the platform files; the tests drive run with a fake.
15	type prober interface {
16		// open returns a connection whose probes leave with the given TTL.
17		open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error)
18	}
19	
20	// probeConn sends one probe and waits for what answers it.
21	type probeConn interface {
22		// send emits the probe and returns the time it left.
23		send() (time.Time, error)
24		// await waits for the answer until the given time. It returns errSilent
25		// when nothing came back by then, and ctx.Err() when ctx ended first.
26		await(ctx context.Context, until time.Time) (reply, error)
27		close() error
28	}
29	
30	// errSilent is await's answer when nothing came back before its deadline.
31	var errSilent = errors.New("no answer before the probe timeout")
32	
33	// probeResult is what one TTL's goroutine hands back. resolved is false when
34	// the probe was cut short (cancellation, deadline, upper TTL no longer needed).
35	type probeResult struct {
36		ttl      int
37		hop      Hop
38		resolved bool
39	}
40	
41	// run traces the path with p. Every connection is opened first, in the
42	// caller's goroutine, so that a failing open stops everything before any
43	// probe is sent; then one goroutine per TTL sends and awaits in parallel.
44	//
45	// onHop, when not nil, is called once per resolved hop, one call at a time and
46	// always from the goroutine that called run, so it needs no lock. It is never
47	// called for an unresolved hop, for a TTL above the terminal one, nor after
48	// run has returned.
49	func run(ctx context.Context, target netip.Addr, opts Options, p prober, onHop func(Hop)) (Result, error) {
50		opts = opts.Normalized()
51		start := time.Now()
52		runCtx, cancel := context.WithTimeout(ctx, opts.Deadline)
53		defer cancel()
54	
55		conns, err := openAll(runCtx, p, target, opts.MaxHops)
56		if err != nil {
57			if runCtx.Err() != nil {
58				return endedEarly(runCtx, target, nil, opts.MaxHops, start), nil
59			}
60			return Result{}, openError(err)
61		}
62		return probeAll(runCtx, target, opts, conns, start, onHop), nil
63	}
64	
65	// openAll opens one connection per TTL, 1 to n. On failure it closes the ones
66	// already open and returns the error.
67	func openAll(ctx context.Context, p prober, target netip.Addr, n int) ([]probeConn, error) {
68		conns := make([]probeConn, 0, n)
69		for ttl := 1; ttl <= n; ttl++ {
70			if err := ctx.Err(); err != nil {
71				closeAll(conns)
72				return nil, err
73			}
74			c, err := p.open(ctx, target, ttl)
75			if err != nil {
76				closeAll(conns)
77				return nil, err
78			}
79			conns = append(conns, c)
80		}
81		return conns, nil
82	}
83	
84	func closeAll(conns []probeConn) {
85		for _, c := range conns {
86			_ = c.close()
87		}
88	}
89	
90	// openError turns a refused socket option (ENOPROTOOPT, EOPNOTSUPP) into
91	// ErrUnsupported, keeping the raw error for the message. Anything else is
92	// returned as is: a refused connect() is not "unsupported", and the system
93	// prober wraps its own socket and setsockopt permission errors itself.
94	func openError(err error) error {
95		for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP} {
96			if errors.Is(err, errno) {
97				return fmt.Errorf("%w: %w", ErrUnsupported, err)
98			}
99		}
100		return err
101	}
102	
103	// probeAll runs phase 2: one goroutine per connection.
104	func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time, onHop func(Hop)) Result {
105		n := len(conns)
106		results := make(chan probeResult, n)
107		cancels := make([]context.CancelFunc, n+1) // indexed by TTL
108		var wg sync.WaitGroup
109		for i, c := range conns {
110			ttl := i + 1
111			var tctx context.Context
112			tctx, cancels[ttl] = context.WithCancel(ctx)
113			wg.Add(1)
114			go func() {
115				defer wg.Done()
116				defer func() { _ = c.close() }()
117				results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
118			}()
119		}
120	
121		t := newTally(n)
122		// collectOne records an answer and streams it when it is a hop worth
123		// showing: resolved, and not above the terminal TTL.
124		collectOne := func(r probeResult) {
125			t.add(r)
126			if onHop == nil || !r.resolved {
127				return
128			}
129			if term := t.terminal(); term > 0 && r.ttl > term {
130				return
131			}
132			onHop(r.hop)
133		}
134		cutAbove := func() {
135			if term := t.terminal(); term > 0 {
136				for ttl := term + 1; ttl <= n; ttl++ {
137					cancels[ttl]()
138				}
139			}
140		}
141	collect:
142		for !t.complete() {
143			select {
144			case r := <-results:
145				collectOne(r)
146				cutAbove()
147			case <-ctx.Done():
148				break collect
149			}
150		}
151		for _, cancel := range cancels[1:] {
152			cancel()
153		}
154		wg.Wait()
155		close(results)
156		for r := range results { // answers that landed while stopping
157			collectOne(r)
158		}
159	
160		if t.complete() {
161			return t.result(target, start)
162		}
163		return endedEarly(ctx, target, t, n, start)
164	}
165	
166	// probeOne sends the probe for one TTL and turns what comes back into a Hop.
167	func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
168		sentAt, err := c.send()
169		if err != nil {
170			if ctx.Err() != nil {
171				return probeResult{ttl: ttl}
172			}
173			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
174		}
175		rep, err := c.await(ctx, sentAt.Add(timeout))
176		recvAt := time.Now()
177		switch {
178		case err != nil && ctx.Err() != nil:
179			return probeResult{ttl: ttl}
180		case errors.Is(err, errSilent):
181			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
182		case err != nil:
183			return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
184		}
185		rtt := rep.RTT
186		if rtt == 0 {
187			rtt = recvAt.Sub(sentAt)
188		}
189		hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
190		return probeResult{ttl: ttl, hop: hop, resolved: true}
191	}
192	
193	// tally collects the resolved hops of a run.
194	type tally struct {
195		hops []probeResult // indexed by TTL, index 0 unused
196	}
197	
198	func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }
199	
200	func (t *tally) add(r probeResult) {
201		if r.resolved {
202			t.hops[r.ttl] = r
203		}
204	}
205	
206	// terminal returns the smallest TTL that reached or was refused, or 0.
207	func (t *tally) terminal() int {
208		for ttl := 1; ttl < len(t.hops); ttl++ {
209			if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
210				return ttl
211			}
212		}
213		return 0
214	}
215	
216	// complete reports whether the trace can end: every TTL up to the terminal
217	// one (or every TTL when there is none) is resolved.
218	func (t *tally) complete() bool {
219		limit := len(t.hops) - 1
220		if term := t.terminal(); term > 0 {
221			limit = term
222		}
223		for ttl := 1; ttl <= limit; ttl++ {
224			if !t.hops[ttl].resolved {
225				return false
226			}
227		}
228		return true
229	}
230	
231	// result builds the Result of a complete tally.
232	func (t *tally) result(target netip.Addr, start time.Time) Result {
233		last, outcome := len(t.hops)-1, OutcomeMaxHops
234		if term := t.terminal(); term > 0 {
235			last = term
236			outcome = OutcomeReached
237			if t.hops[term].hop.Kind == HopUnreachable {
238				outcome = OutcomeUnreachable
239			}
240		}
241		hops := make([]Hop, 0, last)
242		for ttl := 1; ttl <= last; ttl++ {
243			hops = append(hops, t.hops[ttl].hop)
244		}
245		return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
246	}
247	
248	// endedEarly builds the Result of a run that ctx cut short: one entry per TTL
249	// (n entries, index TTL-1), the resolved hops as they are and every other one
250	// as HopUnresolved with its TTL. t is nil when nothing was probed yet.
251	func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
252		res := Result{Target: target, Outcome: OutcomeCancelled, Hops: make([]Hop, 0, n), Duration: time.Since(start)}
253		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
254			res.Outcome = OutcomeDeadline
255		}
256		for ttl := 1; ttl <= n; ttl++ {
257			if t != nil && t.hops[ttl].resolved {
258				res.Hops = append(res.Hops, t.hops[ttl].hop)
259			} else {
260				res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
261			}
262		}
263		return res
264	}
