199	// Calls are sequential even when every probe answers at the same instant.
200	func TestRunCallbackCallsAreSequential(t *testing.T) {
201		const n = 12
202		fp := newFake(n, table(probeSpec{rep: routerReply("10.0.0.1"), delay: 10 * time.Millisecond}, nil)).withBarrier(n)
203		rec := &hopRecorder{nap: 3 * time.Millisecond}
204		res, err := run(context.Background(), engineTarget, Options{MaxHops: n, ProbeTimeout: time.Second}, fp, rec.onHop)
205		rec.finish()
206		if err != nil {
207			t.Fatalf("run: %v", err)
208		}
209		if res.Outcome != OutcomeMaxHops || len(res.Hops) != n {
210			t.Fatalf("Outcome = %v, %d hops; want max hops, %d", res.Outcome, len(res.Hops), n)
211		}
212		rec.check(t)
213		if len(rec.hops) != n {
214			t.Errorf("callback got %d hops, want %d", len(rec.hops), n)
215		}
216		assertBalanced(t, fp)
