219	// Cancel with two hops resolved: the callback saw those two, never an
220	// unresolved one, and never anything once run returned.
221	func TestRunCancelMidTraceStreamsOnlyResolvedHops(t *testing.T) {
222		fp := newFake(5, table(probeSpec{ignoreUntil: true}, map[int]probeSpec{
223			1: {rep: routerReply("10.0.0.1"), delay: 5 * time.Millisecond},
224			2: {rep: routerReply("10.0.0.2"), delay: 10 * time.Millisecond},
225		}))
226		ctx, cancel := context.WithCancel(context.Background())
227		defer cancel()
228		rec := &hopRecorder{also: func(_ Hop, n int) {
229			if n == 2 {
230				cancel()
231			}
232		}}
233		done := make(chan runOut, 1)
234		go func() {
235			res, err := run(ctx, engineTarget, Options{MaxHops: 5, ProbeTimeout: 10 * time.Second}, fp, rec.onHop)
236			rec.finish()
237			done <- runOut{res, err}
238		}()
239		out := waitRun(t, done)
240		if out.err != nil {
241			t.Fatalf("run: %v", out.err)
242		}
243		if out.res.Outcome != OutcomeCancelled {
244			t.Errorf("Outcome = %v, want canceled", out.res.Outcome)
245		}
246		if got, want := rec.ttls(), []int{1, 2}; !sameInts(got, want) {
247			t.Errorf("callback TTLs = %v, want %v", got, want)
248		}
249		rec.check(t)
250		// The Result still carries the unresolved entries; the callback never did.
251		unresolved := 0
252		for _, h := range out.res.Hops {
253			if h.Kind == HopUnresolved {
254				unresolved++
255			}
256		}
257		if unresolved != 3 {
258			t.Errorf("Result has %d unresolved hops, want 3", unresolved)
259		}
260		assertBalanced(t, fp)
261	}
