263	// An answer that lands while the run is stopping is handed over before run
264	// returns (the drain loop), once, and nothing comes after.
265	func TestRunDrainedAnswerIsStreamedBeforeReturn(t *testing.T) {
266		const n = 4
267		ctx, cancel := context.WithCancel(context.Background())
268		defer cancel()
269		fp := newFake(n, table(probeSpec{ignoreUntil: true}, map[int]probeSpec{
270			1: {rep: routerReply("10.0.0.1"), delay: 5 * time.Millisecond},
271		}))
272		fp.onReply = func(int) { cancel() } // the answer races the cancellation
273		rec := &hopRecorder{}
274		done := make(chan runOut, 1)
275		go func() {
276			res, err := run(ctx, engineTarget, Options{MaxHops: n, ProbeTimeout: 10 * time.Second}, fp, rec.onHop)
277			rec.finish()
278			done <- runOut{res, err}
279		}()
280		out := waitRun(t, done)
281		if out.err != nil {
282			t.Fatalf("run: %v", out.err)
283		}
284		rec.check(t)
285		// Whether the answer won the race or not, the callback agrees with the Result.
286		resolved := 0
287		for _, h := range out.res.Hops {
288			if h.Kind != HopUnresolved {
289				resolved++
290			}
291		}
292		if len(rec.hops) != resolved {
293			t.Errorf("callback got %d hops, Result has %d resolved: %+v", len(rec.hops), resolved, out.res.Hops)
294		}
295	}
