297	// An open that fails: no probe, no callback, the error comes back.
298	func TestRunOpenFailureNeverCallsBack(t *testing.T) {
299		routeErr := fmt.Errorf("connect: %w: %w", ErrNoRoute, syscall.ENETUNREACH)
300		fp := newFake(6, table(probeSpec{ignoreUntil: true}, map[int]probeSpec{3: {openErr: routeErr}}))
301		rec := &hopRecorder{}
