303		rec.finish()
304		if !errors.Is(err, ErrNoRoute) || !errors.Is(err, syscall.ENETUNREACH) {
305			t.Fatalf("err = %v, want ErrNoRoute wrapping ENETUNREACH", err)
306		}
307		if len(rec.hops) != 0 {
308			t.Errorf("callback called %d times after an open failure, want never: %+v", len(rec.hops), rec.hops)
309		}
310		if len(res.Hops) != 0 {
311			t.Errorf("Result = %+v, want the zero Result", res)
312		}
313		if got := fp.sends.Load(); got != 0 {
314			t.Errorf("%d probes sent, want none", got)
315		}
316		assertBalanced(t, fp)
317	}
