319	// Trace is TraceEach with a nil callback: the refusals before any probe are
320	// the same, and the callback is never called for them. Platform-neutral: off
321	// Linux both return ErrUnsupported, which is still the same error.
322	func TestTraceEachRefusalsMatchTrace(t *testing.T) {
323		tests := []struct {
324			name   string
325			target netip.Addr
326		}{
327			{"IPv6", netip.MustParseAddr("2001:db8::1")},
328			{"unspecified", netip.MustParseAddr("0.0.0.0")},
329			{"multicast", netip.MustParseAddr("224.0.0.1")},
330			{"limited broadcast", netip.MustParseAddr("255.255.255.255")},
331			{"invalid address", netip.Addr{}},
332		}
333		for _, tc := range tests {
334			t.Run(tc.name, func(t *testing.T) {
335				_, wantErr := Trace(context.Background(), tc.target, Options{})
336				if wantErr == nil {
337					t.Fatal("Trace accepted the target, the case is wrong")
338				}
339				calls := 0
340				res, err := TraceEach(context.Background(), tc.target, Options{}, func(Hop) { calls++ })
341				if !errors.Is(err, wantErr) {
342					t.Errorf("TraceEach err = %v, want the one Trace returns: %v", err, wantErr)
343				}
344				if calls != 0 {
345					t.Errorf("callback called %d times for a refused target", calls)
346				}
347				if len(res.Hops) != 0 || res.Target.IsValid() {
348					t.Errorf("Result = %+v, want the zero Result", res)
349				}
350				if _, err := TraceEach(context.Background(), tc.target, Options{}, nil); !errors.Is(err, wantErr) {
351					t.Errorf("TraceEach with nil callback err = %v, want %v", err, wantErr)
352				}
353			})
354		}
355	}
