1	package netdiag
2	
3	import (
4		"fmt"
5		"net"
6		"strconv"
7		"strings"
8	)
9	
10	// isIPAddress reports whether s is a valid IPv4 or IPv6 address.
11	func isIPAddress(s string) bool {
12		return net.ParseIP(strings.TrimSpace(s)) != nil
13	}
14	
15	// maxHostnameLen is the maximum total length of a DNS name (RFC 1035).
16	const maxHostnameLen = 253
17	
18	// defaultPort is used when the port field is left empty.
19	const defaultPort = "443"
20	
21	// capitalize upper-cases the first letter, so lowercase error strings can be
22	// reused as footer messages (Rule 137).
23	func capitalize(s string) string {
24		if s == "" {
25			return s
26		}
27		return strings.ToUpper(s[:1]) + s[1:]
28	}
29	
30	// isHostname reports whether s is a syntactically valid DNS hostname:
31	// dot-separated labels of 1-63 chars, each made of letters, digits and hyphens,
32	// and not starting or ending with a hyphen.
33	func isHostname(s string) bool {
34		if s == "" || len(s) > maxHostnameLen {
35			return false
36		}
37		for _, label := range strings.Split(strings.TrimSuffix(s, "."), ".") {
38			if len(label) == 0 || len(label) > 63 {
39				return false
40			}
41			if label[0] == '-' || label[len(label)-1] == '-' {
42				return false
43			}
44			for _, r := range label {
45				isAlphaNum := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
46				if !isAlphaNum && r != '-' {
47					return false
48				}
49			}
50		}
51		return true
52	}
53	
54	// validateTarget checks that the target is a usable IP address or hostname.
55	//
56	// Nothing here shells out any more — the openssl pipeline this guard was
57	// written for went with §3.33, and the route trace, the last command that took
58	// the target as an argument, went with §3.47. It is kept because a resolver
59	// asked for "example.com; rm -rf /" should be told the target is malformed
60	// rather than handed it, and because a guard is cheaper to keep than to
61	// reinstate the day something shells out again.
62	func validateTarget(target string) error {
63		if target == "" {
64			return fmt.Errorf("target is required")
65		}
66		if isIPAddress(target) || isHostname(target) {
67			return nil
68		}
69		return fmt.Errorf("target must be a hostname or IP address")
70	}
71	
72	// validatePort checks that the port is a decimal number in the 1-65535 range.
73	func validatePort(port string) error {
74		n, err := strconv.Atoi(port)
75		if err != nil || n < 1 || n > 65535 {
76			return fmt.Errorf("port must be a number between 1 and 65535")
77		}
78		return nil
79	}
